import {searchCharacters, getCharacterById} from './BangumiRequest.js';
import React, {useState, useRef} from 'react';
import debounce from 'lodash.debounce';
import styles from './styles/InputStyles.module.css';
function guassingCharacter() {
    const [inputTerm, setSearchTerm] = useState('');
    const [results, setResults] = useState([]);
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = React.useRef(null);
    const SearchDown = () => {
    const debouncedSearch = debounce(async (searchTerm) => {
        if(!searchTerm){
            setResults(["未找到结果"]);
            return ;
        }
        try{
            const response = await searchCharacters(searchTerm);
            setResults(response);
            setIsOpen(true);
        }catch(error){
            console.error("Error fetching characters:",error);
        }
    },300);
    const handleInputChange = (event) => {
        const value = event.target.value;
        setInputValue(value);
        debouncedSearch(value);
    };
    const handleSelect = async (item) => {
        const response =await getCharacterById(item.id);
        setResults([]);
        setIsOpen(false);
    }
}
    return (
        <div className = "App">
            <div>
                <h1>猜人物</h1>
            </div>
            <div className = "search-dropdown" ref={dropdownRef}>
                <input type="text" value={inputTerm} onChange={handleChange} onFocus={() => setIsOpen(true)} palceholder="输入角色名..." className="search-input"/>
                {isOpen && results.length>0 &&(
                    <ul className="dropdown-list">  
                        {results.map(item => (
                            <li key={item.id} onClick={()=> handleSelect(item)} className="dropdown-item">
                                {item.name}
                                {item.summary && (
                                    <span className="item-item-summary">{item.summary}</span>
                                )}
                            </li>
                        ))}
                    </ul>
                )}
            </div>
        </div>
    )
}
export default guassingCharacter;
